import { readFile, writeFile, mkdir } from "node:fs/promises";
import { createHash } from "node:crypto";
import { normalizeCode } from "../src/services/compile/normalize.ts";
import { compileJob } from "../compiler-service/compile-job.mjs";
import { resolve } from "node:path";
import ts from "typescript";
const normalizer = await readFile("src/services/compile/normalize.ts", "utf8");
await writeFile(
  "compiler-service/normalize-code.mjs",
  "// Generated by pnpm hex:build from src/services/compile/normalize.ts\n" +
    ts.transpileModule(normalizer, {
      compilerOptions: {
        target: ts.ScriptTarget.ES2017,
        module: ts.ModuleKind.ES2022,
      },
    }).outputText,
);
const fixtures = JSON.parse(
  await readFile("src/services/compile/fixtures.json", "utf8"),
);
const sketches = (
  await Promise.all(
    [
      "sketches",
      "hardware-examples",
      "course-sketches",
      "project-sketches",
    ].map(async (n) =>
      JSON.parse(await readFile(`src/content/${n}.json`, "utf8")),
    ),
  )
).flat();
await mkdir("public/hex", { recursive: true });
const index = { version: 1, entries: {} };
for (const sketch of sketches) {
  const hash = createHash("sha256")
    .update(normalizeCode(sketch.code))
    .digest("hex");
  let result = fixtures.find(
    (f) => normalizeCode(f.code) === normalizeCode(sketch.code),
  );
  if (!result?.hex) {
    const windows = process.platform === "win32";
    result = await compileJob(
      sketch.code,
      windows ? resolve("tools/arduino/arduino-cli.exe") : "arduino-cli",
      windows
        ? ["--config-file", resolve("tools/arduino/arduino-cli.yaml")]
        : [],
    );
  }
  if (!result.hex)
    throw Error(`Cannot compile trusted example ${sketch.id}: ${result.error}`);
  await writeFile(`public/hex/${hash}.hex`, result.hex);
  const entry = index.entries[hash] ?? { ids: [], path: `/hex/${hash}.hex` };
  entry.ids.push(sketch.id);
  index.entries[hash] = entry;
}
await writeFile("public/hex/index.json", JSON.stringify(index, null, 2) + "\n");
console.log(
  `${sketches.length} trusted sketches, ${Object.keys(index.entries).length} unique AVR firmware files`,
);
